window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-06fe09d1be4939e9"]={"versions": [{"id": "FIG-06fe09d1be4939e9", "releases": ["R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Softwareschnittstellen für die Diagnose im Kontext des AUTOSAR-Metamodells (TPS Manifest Specification, AUTOSAR Adaptive Platform). Es zeigt die Vererbungshierarchie von Basiselementen zu einer spezifischen Indikatorschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Klassen in vertikaler Generalisierungshierarchie (von oben nach unten):</p>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code> (kursiv, abstrakt): Trägt oben rechts die Markierungen bzw. geerbten Stereotypen/Typen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>.</li>\n<li><code>DiagnosticPortInterface</code> (kursiv, abstrakt): Erbt per geschlossener, nicht ausgefüllter Pfeilspitze von <code>PortInterface</code>.</li>\n<li><code>DiagnosticIndicatorInterface</code> (konkret): Erbt per geschlossener, nicht ausgefüllter Pfeilspitze von <code>DiagnosticPortInterface</code>.</li>\n</ul>\n<p class=\"fig-p\">Attribute und Operationen sind in den Klassen nicht explizit aufgeführt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamisches Verhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Diagnose-Port-Schnittstellen. Eine <code>DiagnosticIndicatorInterface</code> ist ein spezialisiertes <code>DiagnosticPortInterface</code> und fungiert somit als typisiertes <code>PortInterface</code>, das die Eigenschaften eines <code>ARElement</code> sowie der AUTOSAR-Muster <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> übernimmt. Implementierende Werkzeuge müssen diese Vererbungshierarchie bei der Manifest-Erstellung und -Validierung einhalten.</p>"}, {"id": "FIG-40817f9c4fc0927d", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Softwareschnittstellen für die Diagnose im Kontext des AUTOSAR-Metamodells (TPS Manifest Specification, AUTOSAR Adaptive Platform). Es zeigt die Vererbungshierarchie von Basiselementen zu einer spezifischen Indikatorschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei Klassen in vertikaler Generalisierungshierarchie (von oben nach unten):</p>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code> (kursiv, abstrakt): Trägt oben rechts die Markierungen bzw. geerbten Stereotypen/Typen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>.</li>\n<li><code>DiagnosticPortInterface</code> (kursiv, abstrakt): Erbt per geschlossener, nicht ausgefüllter Pfeilspitze von <code>PortInterface</code>.</li>\n<li><code>DiagnosticIndicatorInterface</code> (konkret): Erbt per geschlossener, nicht ausgefüllter Pfeilspitze von <code>DiagnosticPortInterface</code>.</li>\n</ul>\n<p class=\"fig-p\">Attribute und Operationen sind in den Klassen nicht explizit aufgeführt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamisches Verhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Diagnose-Port-Schnittstellen. Eine <code>DiagnosticIndicatorInterface</code> ist ein spezialisiertes <code>DiagnosticPortInterface</code> und fungiert somit als typisiertes <code>PortInterface</code>, das die Eigenschaften eines <code>ARElement</code> sowie der AUTOSAR-Muster <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> übernimmt. Implementierende Werkzeuge müssen diese Vererbungshierarchie bei der Manifest-Erstellung und -Validierung einhalten.</p>"}, {"id": "FIG-f256820c36395fa4", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Softwareschnittstellen für die Diagnose im Kontext des AUTOSAR-Metamodells (TPS Manifest Specification, AUTOSAR Adaptive Platform). Es zeigt die Vererbungshierarchie von Basiselementen zur spezifischen Indikatorschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei Klassenblöcke in vertikaler Generalisierungshierarchie (von oben nach unten):</p>\n<ul class=\"fig-list\">\n<li>Oberer Block: Enthält <code>PortInterface</code> (kursiv, oben rechts) und <code>DiagnosticPortInterface</code> (kursiv, zentriert).</li>\n<li><code>DiagnosticIndicatorInterface</code>: Konkrete Schnittstellenklasse, erbt per geschlossener, nicht ausgefüllter Pfeilspitze vom übergeordneten Klassenblock (<code>DiagnosticPortInterface</code> / <code>PortInterface</code>).</li>\n</ul>\n<p class=\"fig-p\">Attribute und Operationen sind nicht explizit aufgeführt. Die Tags <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamisches Verhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Diagnose-Port-Schnittstellen. Eine <code>DiagnosticIndicatorInterface</code> leitet sich von <code>DiagnosticPortInterface</code> und <code>PortInterface</code> ab. Für die Modellierung von Diagnose-Indikatoren im Manifest ist die Klassenidentität <code>DiagnosticIndicatorInterface</code> als PortInterface-Spezialisierung maßgeblich.</p>"}, {"id": "FIG-870cb36fb77781bf", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Softwareschnittstellen für die Diagnose im Kontext des AUTOSAR-Metamodells (TPS Manifest Specification, AUTOSAR Adaptive Platform). Es zeigt die Vererbungshierarchie von Basiselementen zur spezifischen Indikatorschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei Klassenblöcke in vertikaler Generalisierungshierarchie (von oben nach unten):</p>\n<ul class=\"fig-list\">\n<li>Oberer Block: Enthält <code>PortInterface</code> (kursiv, oben rechts) und <code>DiagnosticPortInterface</code> (kursiv, zentriert).</li>\n<li><code>DiagnosticIndicatorInterface</code>: Konkrete Schnittstellenklasse, erbt per geschlossener, nicht ausgefüllter Pfeilspitze vom übergeordneten Klassenblock (<code>DiagnosticPortInterface</code> / <code>PortInterface</code>).</li>\n</ul>\n<p class=\"fig-p\">Attribute und Operationen sind nicht explizit aufgeführt. Die Tags <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamisches Verhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Diagnose-Port-Schnittstellen. Eine <code>DiagnosticIndicatorInterface</code> leitet sich von <code>DiagnosticPortInterface</code> und <code>PortInterface</code> ab. Für die Modellierung von Diagnose-Indikatoren im Manifest ist die Klassenidentität <code>DiagnosticIndicatorInterface</code> als PortInterface-Spezialisierung maßgeblich.</p>"}, {"id": "FIG-8f14b403eef3903c", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Softwareschnittstellen für die Diagnose im Kontext des AUTOSAR-Metamodells (TPS Manifest Specification, AUTOSAR Adaptive Platform). Es zeigt die Vererbungshierarchie von Basiselementen zur spezifischen Indikatorschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei Klassenblöcke in vertikaler Generalisierungshierarchie (von oben nach unten):</p>\n<ul class=\"fig-list\">\n<li>Oberer Block: Enthält <code>PortInterface</code> (kursiv, oben rechts) und <code>DiagnosticPortInterface</code> (kursiv, zentriert).</li>\n<li><code>DiagnosticIndicatorInterface</code>: Konkrete Schnittstellenklasse, erbt per geschlossener, nicht ausgefüllter Pfeilspitze vom übergeordneten Klassenblock (<code>DiagnosticPortInterface</code> / <code>PortInterface</code>).</li>\n</ul>\n<p class=\"fig-p\">Attribute und Operationen sind nicht explizit aufgeführt. Die Tags <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamisches Verhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Diagnose-Port-Schnittstellen. Eine <code>DiagnosticIndicatorInterface</code> leitet sich von <code>DiagnosticPortInterface</code> und <code>PortInterface</code> ab. Für die Modellierung von Diagnose-Indikatoren im Manifest ist die Klassenidentität <code>DiagnosticIndicatorInterface</code> als PortInterface-Spezialisierung maßgeblich.</p>"}, {"id": "FIG-ec264e406fded498", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Softwareschnittstellen für die Diagnose im Kontext des AUTOSAR-Metamodells (TPS Manifest Specification, AUTOSAR Adaptive Platform). Es zeigt die Vererbungshierarchie von Basiselementen zur spezifischen Indikatorschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei Klassenblöcke in vertikaler Generalisierungshierarchie (von oben nach unten):</p>\n<ul class=\"fig-list\">\n<li>Oberer Block: Enthält <code>PortInterface</code> (kursiv, oben rechts) und <code>DiagnosticPortInterface</code> (kursiv, zentriert).</li>\n<li><code>DiagnosticIndicatorInterface</code>: Konkrete Schnittstellenklasse, erbt per geschlossener, nicht ausgefüllter Pfeilspitze vom übergeordneten Klassenblock (<code>DiagnosticPortInterface</code> / <code>PortInterface</code>).</li>\n</ul>\n<p class=\"fig-p\">Attribute und Operationen sind nicht explizit aufgeführt. Die Tags <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamisches Verhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Diagnose-Port-Schnittstellen. Eine <code>DiagnosticIndicatorInterface</code> leitet sich von <code>DiagnosticPortInterface</code> und <code>PortInterface</code> ab. Für die Modellierung von Diagnose-Indikatoren im Manifest ist die Klassenidentität <code>DiagnosticIndicatorInterface</code> als PortInterface-Spezialisierung maßgeblich.</p>"}, {"id": "FIG-edcd7bf820e202dd", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Softwareschnittstellen für die Diagnose im Kontext des AUTOSAR-Metamodells (TPS Manifest Specification, AUTOSAR Adaptive Platform). Es zeigt die Vererbungshierarchie von Basiselementen zur spezifischen Indikatorschnittstelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zwei Klassenblöcke in vertikaler Generalisierungshierarchie (von oben nach unten):</p>\n<ul class=\"fig-list\">\n<li>Oberer Block: Enthält <code>PortInterface</code> (kursiv, oben rechts) und <code>DiagnosticPortInterface</code> (kursiv, zentriert).</li>\n<li><code>DiagnosticIndicatorInterface</code>: Konkrete Schnittstellenklasse, erbt per geschlossener, nicht ausgefüllter Pfeilspitze vom übergeordneten Klassenblock (<code>DiagnosticPortInterface</code> / <code>PortInterface</code>).</li>\n</ul>\n<p class=\"fig-p\">Attribute und Operationen sind nicht explizit aufgeführt. Die Tags <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamisches Verhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für Diagnose-Port-Schnittstellen. Eine <code>DiagnosticIndicatorInterface</code> leitet sich von <code>DiagnosticPortInterface</code> und <code>PortInterface</code> ab. Für die Modellierung von Diagnose-Indikatoren im Manifest ist die Klassenidentität <code>DiagnosticIndicatorInterface</code> als PortInterface-Spezialisierung maßgeblich.</p>"}], "trans": [{"from": "FIG-06fe09d1be4939e9", "to": "FIG-40817f9c4fc0927d", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-40817f9c4fc0927d", "to": "FIG-f256820c36395fa4", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>PortInterface: Die Generalisierungshierarchie entfällt in der Darstellung; die Spezialisierungen ARElement, AtpBlueprint, AtpBlueprintable und AtpType am oberen Block werden entfernt.</li>\n<li>DiagnosticPortInterface: Ist nun direkt als vererbende Basisklasse im oberen Block zusammengefasst dargestellt, auf die DiagnosticIndicatorInterface per Generalisierungspfad verweist.</li>\n</ul>"}, {"from": "FIG-f256820c36395fa4", "to": "FIG-870cb36fb77781bf", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-870cb36fb77781bf", "to": "FIG-8f14b403eef3903c", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8f14b403eef3903c", "to": "FIG-ec264e406fded498", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ec264e406fded498", "to": "FIG-edcd7bf820e202dd", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
